#!/usr/bin/env python3
import json
import sys
from itertools import product

# Define the sets of attributes.
NAMES = ["Eric", "Bob", "Peter", "Alice", "Arnold", "Carol"]
CARS = ["ford f150", "honda civic", "toyota camry", "tesla model 3", "chevrolet silverado", "bmw 3 series"]
MOTHERS = ["Sarah", "Penny", "Holly", "Aniya", "Kailyn", "Janelle"]
HOBBIES = ["photography", "cooking", "knitting", "gardening", "woodworking", "painting"]

# We use 6 houses (index 0 to 5 correspond to House 1 ... House 6)
NUM_HOUSES = 6

def check_partial(assignment):
    """
    Check the constraints that involve the houses in the current partial assignment.
    assignment is a list of dicts with keys: "Name", "Car", "Mother", "Hobby".
    Their position in the list corresponds to the house number (0-indexed).
    Returns True if constraints are satisfied so far, False otherwise.
    """
    n = len(assignment)

    # For each house in assignment, check forced individual constraints:
    for i, house in enumerate(assignment):
        name = house["Name"]
        car = house["Car"]
        mother = house["Mother"]
        hobby = house["Hobby"]

        # If name is Eric, then hobby must be gardening.
        if name == "Eric" and hobby != "gardening":
            return False
        # If name is Carol, then hobby must be photography.
        if name == "Carol" and hobby != "photography":
            return False
        # If name is Arnold, then car must be honda civic.
        if name == "Arnold" and car != "honda civic":
            return False
        # If name is Bob, then car must be bmw 3 series.
        if name == "Bob" and car != "bmw 3 series":
            return False
        # If car is honda civic, then name must be Arnold.
        if car == "honda civic" and name != "Arnold":
            return False
        # If car is bmw 3 series, then name must be Bob.
        if car == "bmw 3 series" and name != "Bob":
            return False
        # If car is chevrolet silverado, then mother must be Aniya.
        if car == "chevrolet silverado" and mother != "Aniya":
            return False
        # If mother is Aniya, then car must be chevrolet silverado.
        if mother == "Aniya" and car != "chevrolet silverado":
            return False
        # If car is ford f150, then mother must be Sarah.
        if car == "ford f150" and mother != "Sarah":
            return False

        # Special fixed position constraints:
        # House 4 (index 3) must have car "ford f150" and mother "Sarah"
        if i == 3:
            if car != "ford f150" or mother != "Sarah":
                return False
        # House 6 (index 5) must have car "toyota camry", mother "Kailyn", and hobby "cooking"
        if i == 5:
            if car != "toyota camry" or mother != "Kailyn" or hobby != "cooking":
                return False
        # The person with chevrolet silverado cannot be in House 2 (index 1)
        if i == 1 and car == "chevrolet silverado":
            return False

    # Ordering and adjacent constraints that can be checked if the relevant houses are assigned:
    # Constraint 8 and 17: Eric is directly left of the person who enjoys knitting,
    # and the person whose mother's name is Holly is directly left of the person who enjoys knitting.
    # So for any house i (>=1) that has hobby "knitting", check that house (i-1) exists and has Name == "Eric",
    # Mother == "Holly", and hobby == "gardening".
    for i in range(1, n):
        if assignment[i]["Hobby"] == "knitting":
            prev = assignment[i-1]
            if prev["Name"] != "Eric" or prev["Mother"] != "Holly" or prev["Hobby"] != "gardening":
                return False

    # Constraint 14: The woodworking hobbyist is somewhere to the left of the person who enjoys knitting.
    # If a house with "knitting" is assigned, then at least one house with "woodworking" must appear with a lower index.
    for i in range(n):
        if assignment[i]["Hobby"] == "knitting":
            found = False
            for j in range(i):
                if assignment[j]["Hobby"] == "woodworking":
                    found = True
                    break
            if not found:
                return False

    # Constraint 10: The person whose mother's name is Penny is somewhere to the right of the person who enjoys knitting.
    # If both exist in the partial assignment, then index(Penny) > index(knitting)
    index_knitting = None
    index_penny = None
    for i, house in enumerate(assignment):
        if house["Hobby"] == "knitting":
            index_knitting = i
        if house["Mother"] == "Penny":
            index_penny = i
    if index_knitting is not None and index_penny is not None:
        if index_penny <= index_knitting:
            return False

    # Constraint 11: The person whose mother's name is Aniya is somewhere to the right of the person who owns a Honda Civic.
    index_honda = None
    index_aniya = None
    for i, house in enumerate(assignment):
        if house["Car"] == "honda civic":
            index_honda = i
        if house["Mother"] == "Aniya":
            index_aniya = i
    if index_honda is not None and index_aniya is not None:
        if index_aniya <= index_honda:
            return False

    # Constraint 12: Alice is somewhere to the right of the person who owns a Ford F-150.
    index_f150 = None
    index_alice = None
    for i, house in enumerate(assignment):
        if house["Car"] == "ford f150":
            index_f150 = i
        if house["Name"] == "Alice":
            index_alice = i
    if index_f150 is not None and index_alice is not None:
        if index_alice <= index_f150:
            return False

    # Constraint 15: There is one house between the person whose mother's name is Sarah and the person who loves cooking.
    index_sarah = None
    index_cooking = None
    for i, house in enumerate(assignment):
        if house["Mother"] == "Sarah":
            index_sarah = i
        if house["Hobby"] == "cooking":
            index_cooking = i
    if index_sarah is not None and index_cooking is not None:
        if abs(index_cooking - index_sarah) != 2:
            return False

    # Constraint 9: There is one house between the person whose mother's name is Sarah and the person who owns a Toyota Camry.
    index_camry = None
    for i, house in enumerate(assignment):
        if house["Car"] == "toyota camry":
            index_camry = i
    if index_sarah is not None and index_camry is not None:
        if abs(index_camry - index_sarah) != 2:
            return False

    return True

def backtrack(i, assignment, names_left, cars_left, mothers_left, hobbies_left):
    if i == NUM_HOUSES:
        # Full assignment complete; check final constraints.
        if check_partial(assignment):
            return assignment
        else:
            return None
    # For house i, generate candidate quadruples from available values.
    # We'll iterate over all combinations from the remaining choices.
    for name in names_left:
        for car in cars_left:
            for mother in mothers_left:
                for hobby in hobbies_left:
                    # Make a candidate house assignment.
                    candidate = {"Name": name, "Car": car, "Mother": mother, "Hobby": hobby}

                    # Forced position constraints:
                    # House 4 (index 3) must have car "ford f150" and mother "Sarah"
                    if i == 3:
                        if car != "ford f150" or mother != "Sarah":
                            continue
                    # House 6 (index 5) must have car "toyota camry", mother "Kailyn", and hobby "cooking"
                    if i == 5:
                        if car != "toyota camry" or mother != "Kailyn" or hobby != "cooking":
                            continue

                    # Forced individual attribute relations:
                    # If name is Eric then hobby must be gardening.
                    if name == "Eric" and hobby != "gardening":
                        continue
                    # If name is Carol then hobby must be photography.
                    if name == "Carol" and hobby != "photography":
                        continue
                    # If name is Arnold then car must be honda civic.
                    if name == "Arnold" and car != "honda civic":
                        continue
                    # If name is Bob then car must be bmw 3 series.
                    if name == "Bob" and car != "bmw 3 series":
                        continue
                    # Conversely, if car is honda civic, then name must be Arnold.
                    if car == "honda civic" and name != "Arnold":
                        continue
                    # If car is bmw 3 series, then name must be Bob.
                    if car == "bmw 3 series" and name != "Bob":
                        continue
                    # If car is chevrolet silverado then mother must be Aniya.
                    if car == "chevrolet silverado" and mother != "Aniya":
                        continue
                    # Conversely, if mother is Aniya then car must be chevrolet silverado.
                    if mother == "Aniya" and car != "chevrolet silverado":
                        continue
                    # If car is ford f150 then mother must be Sarah.
                    if car == "ford f150" and mother != "Sarah":
                        continue

                    # Also, the person with chevrolet silverado cannot be in House 2 (index 1)
                    if i == 1 and car == "chevrolet silverado":
                        continue

                    # Create new available sets after using this candidate.
                    new_names = [x for x in names_left if x != name]
                    new_cars = [x for x in cars_left if x != car]
                    new_mothers = [x for x in mothers_left if x != mother]
                    new_hobbies = [x for x in hobbies_left if x != hobby]

                    new_assignment = assignment + [candidate]

                    # Check partial constraints using new_assignment.
                    if not check_partial(new_assignment):
                        continue

                    result = backtrack(i+1, new_assignment, new_names, new_cars, new_mothers, new_hobbies)
                    if result is not None:
                        return result
    return None

def solve_puzzle():
    solution = backtrack(0, [], NAMES, CARS, MOTHERS, HOBBIES)
    return solution

def main():
    sol = solve_puzzle()
    if sol is None:
        output = {"solution": {"header": ["House", "Name", "Car", "Mother", "Hobby"], "rows": []}}
    else:
        # The houses are in order from index 0 to NUM_HOUSES-1; House numbers are 1 thru 6.
        rows = []
        for i, house in enumerate(sol):
            row = [str(i+1), house["Name"], house["Car"], house["Mother"], house["Hobby"]]
            rows.append(row)
        output = {"solution": {"header": ["House", "Name", "Car", "Mother", "Hobby"], "rows": rows}}
    print(json.dumps(output, indent=2))

if __name__ == "__main__":
    main()
